import itertools

def is_costas(perm):
    n = len(perm)
    diffs = set()
    for i in range(n):
        for j in range(i+1, n):
            dc = j - i
            dr = perm[j] - perm[i]
            if (dc, dr) in diffs:
                return False
            diffs.add((dc, dr))
    return True

fixed = {3:8, 8:2}
positions = [i for i in range(12) if i not in fixed]
values = [i for i in range(12) if i not in fixed.values()]

for perm_vals in itertools.permutations(values):
    perm = [0]*12
    for pos, val in zip(positions, perm_vals):
        perm[pos] = val
    for pos, val in fixed.items():
        perm[pos] = val
    if is_costas(perm):
        print(perm)
        break
else:
    print("No solution")
